-- =============================================================================
-- STOCK SNAPSHOT DATA (Initial inventory)
-- =============================================================================

-- Casa Central (main retail)
INSERT INTO stock_snapshot (id, branch_id, product_id, quantity, reserved_quantity, last_updated)
SELECT
    gen_random_uuid(),
    'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',
    id,
    CASE
        WHEN unit_price > 200000 THEN floor(random() * 5 + 2)::numeric  -- High value items: 2-6
        WHEN unit_price > 50000 THEN floor(random() * 15 + 5)::numeric  -- Medium value: 5-19
        ELSE floor(random() * 30 + 10)::numeric  -- Low value items: 10-39
    END,
    0,
    NOW()
FROM product
WHERE tenant_id = '11111111-1111-1111-1111-111111111111';

-- Sucursal Norte (secondary retail)
INSERT INTO stock_snapshot (id, branch_id, product_id, quantity, reserved_quantity, last_updated)
SELECT
    gen_random_uuid(),
    'bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb',
    id,
    CASE
        WHEN unit_price > 200000 THEN floor(random() * 3 + 1)::numeric
        WHEN unit_price > 50000 THEN floor(random() * 10 + 3)::numeric
        ELSE floor(random() * 20 + 5)::numeric
    END,
    0,
    NOW()
FROM product
WHERE tenant_id = '11111111-1111-1111-1111-111111111111';

-- Sucursal Zona Oeste (smallest retail)
INSERT INTO stock_snapshot (id, branch_id, product_id, quantity, reserved_quantity, last_updated)
SELECT
    gen_random_uuid(),
    'cccccccc-cccc-cccc-cccc-cccccccccccc',
    id,
    CASE
        WHEN unit_price > 200000 THEN floor(random() * 2 + 1)::numeric
        WHEN unit_price > 50000 THEN floor(random() * 8 + 2)::numeric
        ELSE floor(random() * 15 + 3)::numeric
    END,
    0,
    NOW()
FROM product
WHERE tenant_id = '11111111-1111-1111-1111-111111111111';

-- Deposito Central (warehouse - larger quantities)
INSERT INTO stock_snapshot (id, branch_id, product_id, quantity, reserved_quantity, last_updated)
SELECT
    gen_random_uuid(),
    'dddddddd-dddd-dddd-dddd-dddddddddddd',
    id,
    CASE
        WHEN unit_price > 200000 THEN floor(random() * 10 + 5)::numeric
        WHEN unit_price > 50000 THEN floor(random() * 30 + 15)::numeric
        ELSE floor(random() * 80 + 30)::numeric
    END,
    0,
    NOW()
FROM product
WHERE tenant_id = '11111111-1111-1111-1111-111111111111';

-- =============================================================================
-- INITIAL STOCK MOVEMENTS (PURCHASE type for initial stock)
-- =============================================================================

INSERT INTO stock_movement (id, tenant_id, branch_id, product_id, quantity_delta, cost_snapshot, type, notes, created_at)
SELECT
    gen_random_uuid(),
    '11111111-1111-1111-1111-111111111111',
    ss.branch_id,
    ss.product_id,
    ss.quantity,
    p.cost_price,
    'PURCHASE',
    'Stock inicial de apertura',
    NOW() - interval '30 days'
FROM stock_snapshot ss
JOIN product p ON ss.product_id = p.id
WHERE p.tenant_id = '11111111-1111-1111-1111-111111111111';

